import{_ as a,o as e,c as d,a2 as l}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"判断推理","description":"","frontmatter":{},"headers":[],"relativePath":"xingce/panduan-tuili.md","filePath":"xingce/panduan-tuili.md"}'),r={name:"xingce/panduan-tuili.md"};function i(n,t,s,o,h,u){return e(),d("div",null,[...t[0]||(t[0]=[l(`<h1 id="判断推理" tabindex="-1">判断推理 <a class="header-anchor" href="#判断推理" aria-label="Permalink to &quot;判断推理&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>判断推理考察逻辑思维能力，是行测中第二大模块（约 35-40 题）。</p><h2 id="📊-四大题型" tabindex="-1">📊 四大题型 <a class="header-anchor" href="#📊-四大题型" aria-label="Permalink to &quot;📊 四大题型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>题型</th><th>题量</th><th>特点</th></tr></thead><tbody><tr><td>图形推理</td><td>10</td><td>找规律，多练就熟了</td></tr><tr><td>定义判断</td><td>10</td><td>最稳，逐项对照即可</td></tr><tr><td>类比推理</td><td>10</td><td>速度快，1分钟3题</td></tr><tr><td>逻辑判断</td><td>10</td><td>最难，需要推理框架</td></tr></tbody></table><hr><h2 id="一、图形推理" tabindex="-1">一、图形推理 <a class="header-anchor" href="#一、图形推理" aria-label="Permalink to &quot;一、图形推理&quot;">​</a></h2><h3 id="常见规律类型" tabindex="-1">常见规律类型 <a class="header-anchor" href="#常见规律类型" aria-label="Permalink to &quot;常见规律类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>规律</th><th>特征</th><th>示例思路</th></tr></thead><tbody><tr><td>位置类</td><td>图形平移、旋转、翻转</td><td>看元素移动方向</td></tr><tr><td>样式类</td><td>叠加、求同、求异</td><td>看图形间运算</td></tr><tr><td>数量类</td><td>点、线、面、角、笔画数</td><td>数完之后找规律</td></tr><tr><td>属性类</td><td>对称、曲直、封闭开放</td><td>看整体特征</td></tr><tr><td>空间类</td><td>折纸盒、三视图</td><td>空间想象力</td></tr></tbody></table><h3 id="解题步骤" tabindex="-1">解题步骤 <a class="header-anchor" href="#解题步骤" aria-label="Permalink to &quot;解题步骤&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 判断图形组成 → 元素相同？（位置类）</span></span>
<span class="line"><span>                 → 元素相似？（样式类）</span></span>
<span class="line"><span>                 → 元素不同？（先数数量，再看属性）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 数量类数什么？→ 先数面 → 再数线 → 再数点 → 再数笔画</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><hr><h2 id="二、定义判断" tabindex="-1">二、定义判断 <a class="header-anchor" href="#二、定义判断" aria-label="Permalink to &quot;二、定义判断&quot;">​</a></h2><h3 id="解题方法" tabindex="-1">解题方法 <a class="header-anchor" href="#解题方法" aria-label="Permalink to &quot;解题方法&quot;">​</a></h3><blockquote><p><strong>关键</strong>：题干定义是唯一标准，不要用生活常识代替定义！</p></blockquote><p><strong>步骤</strong>：</p><ol><li>提取定义的关键要素（主体、对象、条件、结果）</li><li>逐一对照选项，排除不符合的</li><li>选最符合的那个</li></ol><p><strong>常见陷阱</strong>：</p><ul><li>主体偷换（定义说的是&quot;企业&quot;，选项说&quot;个人&quot;）</li><li>条件缺失（定义要求同时满足 A 和 B，选项只满足 A）</li><li>结果偏差（定义的结果是积极的，选项结果是消极的）</li></ul><hr><h2 id="三、类比推理" tabindex="-1">三、类比推理 <a class="header-anchor" href="#三、类比推理" aria-label="Permalink to &quot;三、类比推理&quot;">​</a></h2><h3 id="常见关系类型" tabindex="-1">常见关系类型 <a class="header-anchor" href="#常见关系类型" aria-label="Permalink to &quot;常见关系类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>关系</th><th>示例</th></tr></thead><tbody><tr><td>种属关系</td><td>苹果 : 水果（苹果是水果的一种）</td></tr><tr><td>组成关系</td><td>轮胎 : 汽车（轮胎是汽车的组成部分）</td></tr><tr><td>功能关系</td><td>笔 : 书写</td></tr><tr><td>因果关系</td><td>下雨 : 地湿</td></tr><tr><td>近义/反义</td><td>美丽 : 漂亮 / 前进 : 后退</td></tr><tr><td>顺序关系</td><td>申请 : 审批 : 执行</td></tr></tbody></table><h3 id="解题技巧" tabindex="-1">解题技巧 <a class="header-anchor" href="#解题技巧" aria-label="Permalink to &quot;解题技巧&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先造句子 → &quot;A 是 B 的一种&quot; → 看选项谁最像</span></span>
<span class="line"><span>         → &quot;A 用来做 B&quot;    → 横向/纵向对比</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><hr><h2 id="四、逻辑判断" tabindex="-1">四、逻辑判断 <a class="header-anchor" href="#四、逻辑判断" aria-label="Permalink to &quot;四、逻辑判断&quot;">​</a></h2><h3 id="翻译推理-形式逻辑" tabindex="-1">翻译推理（形式逻辑） <a class="header-anchor" href="#翻译推理-形式逻辑" aria-label="Permalink to &quot;翻译推理（形式逻辑）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>逻辑关系</th><th>翻译</th><th>逆否等价</th></tr></thead><tbody><tr><td>如果 A 那么 B</td><td>A → B</td><td>¬B → ¬A</td></tr><tr><td>只有 A 才 B</td><td>B → A</td><td>¬A → ¬B</td></tr><tr><td>A 且 B</td><td>A ∧ B</td><td>否定为 ¬A ∨ ¬B</td></tr><tr><td>A 或 B</td><td>A ∨ B</td><td>否定为 ¬A ∧ ¬B</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">⚠️ 常考点</p><ul><li>&quot;如果就&quot; = 前推后（充分条件）</li><li>&quot;只有才&quot; = 后推前（必要条件）</li><li>逆否命题一定等价于原命题</li><li>否命题和逆命题都不等价！</li></ul></div><h3 id="加强-削弱题" tabindex="-1">加强/削弱题 <a class="header-anchor" href="#加强-削弱题" aria-label="Permalink to &quot;加强/削弱题&quot;">​</a></h3><p><strong>加强</strong>（让结论更可信）：</p><ul><li>补充正面证据</li><li>排除他因</li><li>搭桥（建立前提和结论的联系）</li></ul><p><strong>削弱</strong>（让结论不可信）：</p><ul><li>因果倒置</li><li>他因削弱</li><li>切断联系</li><li>否定前提</li></ul><h3 id="结论型" tabindex="-1">结论型 <a class="header-anchor" href="#结论型" aria-label="Permalink to &quot;结论型&quot;">​</a></h3><p>逐个选项对照题干信息，排除无中生有的选项。</p><hr><h2 id="📝-我的备考笔记" tabindex="-1">📝 我的备考笔记 <a class="header-anchor" href="#📝-我的备考笔记" aria-label="Permalink to &quot;📝 我的备考笔记&quot;">​</a></h2><h3 id="图形推理薄弱类型" tabindex="-1">图形推理薄弱类型 <a class="header-anchor" href="#图形推理薄弱类型" aria-label="Permalink to &quot;图形推理薄弱类型&quot;">​</a></h3><ol><li></li><li></li></ol><h3 id="逻辑判断题错因分析" tabindex="-1">逻辑判断题错因分析 <a class="header-anchor" href="#逻辑判断题错因分析" aria-label="Permalink to &quot;逻辑判断题错因分析&quot;">​</a></h3><ol><li></li><li></li></ol><h3 id="类比推理积累的关系" tabindex="-1">类比推理积累的关系 <a class="header-anchor" href="#类比推理积累的关系" aria-label="Permalink to &quot;类比推理积累的关系&quot;">​</a></h3><ol><li></li><li></li></ol>`,45)])])}const b=a(r,[["render",i]]);export{c as __pageData,b as default};
